def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by(items, key_fn, default=None):
        it = list(items or [])
        if not it:
            return default
        best = it[0]
        best_key = key_fn(best)
        for x in it[1:]:
            k = key_fn(x)
            if k < best_key:
                best = x
                best_key = k
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position") or [0, 0]
    opp_pos = observation.get("opponent_position") or [self_pos[0], self_pos[1]]
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    cx = (w - 1) / 2 if w else sx
    cy = (h - 1) / 2 if h else sy

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            pred = [ox, oy]
            odx, ody = observation.get("opponent_velocity") or [0, 0]
            if odx or ody:
                pred = [ox + odx, oy + ody]
            return step_toward([sx, sy], pred)

        corners = []
        if w and h:
            corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        else:
            corners = [[sx - 2, sy - 2], [sx - 2, sy + 2], [sx + 2, sy - 2], [sx + 2, sy + 2]]

        target = best_by(
            corners,
            lambda p: (manhattan(p, [ox, oy]), manhattan(p, [sx, sy])),
            default=[sx, sy],
        )
        return step_toward([sx, sy], target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        if targets:
            target = best_by(
                targets,
                lambda p: (manhattan(p, [sx, sy]), manhattan(p, [ox, oy])),
                default=[sx, sy],
            )
            return step_toward([sx, sy], target)

        if w and h:
            return step_toward([sx, sy], [cx, cy])
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = best_by(
            resources,
            lambda p: (manhattan(p, [sx, sy]), manhattan(p, [ox, oy])),
            default=[sx, sy],
        )
        return step_toward([sx, sy], target)

    if w and h:
        home = [cx, cy]
        return step_toward([sx, sy], home)

    return step_toward([sx, sy], [ox, oy])

